  id: string;
  label: string;
  interval: string;
  coins: string[];
  hasExperiments: boolean;
  experimentCount: number;
  hasEquityCurve: boolean;
  equityCurves: string[];
  hasAudit: boolean;
  hasPaperTrading: boolean;
}

