// ---- Manifest ----

export async function fetchManifest(): Promise<StrategyManifest | null> {
  try {
    const res = await fetch(`${BASE}/data/manifest.json`);
    if (!res.ok) return null;
    return res.json();
  } catch {
    return null;
  }
}

// ---- Strategy-aware data path helpers ----

function strategyPath(strategyId: string | undefined, filename: string): string {
  if (strategyId) {
    return `${BASE}/data/strategies/${strategyId}/${filename}`;
  }
  // Legacy fallback
  return `${BASE}/data/${filename}`;
}

