import { useState, useRef, useEffect } from "react";
import { cn } from "@/lib/utils";
import { useStrategy } from "@/lib/strategy-context";

const links = [
  { href: "/", label: "Overview" },
  { href: "/strategy-lab", label: "Strategy Lab" },
  { href: "/score-evolution", label: "AI Score Evolution" },
  { href: "/regime", label: "Regime Analysis" },
];

export function Nav() {
  const pathname = usePathname();
  const {
    strategies,
    selectedStrategy,
    selectedId,
    setSelectedId,
    loading,
  } = useStrategy();

  const [open, setOpen] = useState(false);
  const dropdownRef = useRef<HTMLDivElement>(null);

  // Close dropdown on outside click
  useEffect(() => {
    function handleClick(e: MouseEvent) {
      if (dropdownRef.current && !dropdownRef.current.contains(e.target as Node)) {
        setOpen(false);
      }
    }
    document.addEventListener("mousedown", handleClick);
    return () => document.removeEventListener("mousedown", handleClick);
  }, []);

  const hasActivity = (strat: typeof strategies[0]) =>
    strat.hasExperiments || strat.hasPaperTrading;

  // Sort: active strategies first, then inactive
  const sortedStrategies = [...strategies].sort((a, b) => {
    const aActive = hasActivity(a) ? 0 : 1;
    const bActive = hasActivity(b) ? 0 : 1;
    return aActive - bActive;
  });

  return (
    <header className="border-b border-border bg-card">
      <div className="max-w-7xl mx-auto px-4 sm:px-6">
        <div className="flex items-center justify-between h-14">
          <div className="flex items-center gap-4">
            <div className="flex items-center gap-2">
              <div className="h-3 w-3 rounded-full bg-emerald-500 animate-pulse" />
              <span className="font-mono text-sm font-semibold tracking-tight">
                AutoResearch
              </span>
            </div>

            {/* Strategy Dropdown */}
            {!loading && strategies.length > 0 && (
              <div className="relative" ref={dropdownRef}>
                <button
                  onClick={() => setOpen(!open)}
                  className={cn(
                    "flex items-center gap-2 px-3 py-1.5 rounded-md text-xs font-mono transition-colors border",
                    "bg-muted border-border hover:bg-muted/80"
                  )}
                >
                  {selectedStrategy && (
                    <>
                      <span className="font-semibold text-foreground">
                        {selectedStrategy.label}
                      </span>
                      {selectedStrategy.hasPaperTrading && (
                        <span className="h-1.5 w-1.5 rounded-full bg-emerald-500 animate-pulse" />
                      )}
                      {selectedStrategy.hasExperiments && (
                        <span className="text-muted-foreground">
                          {selectedStrategy.experimentCount} exp
                        </span>
                      )}
                    </>
                  )}
                  <svg
                    className={cn(
                      "w-3 h-3 text-muted-foreground transition-transform",
                      open && "rotate-180"
                    )}
                    fill="none"
                    stroke="currentColor"
                    viewBox="0 0 24 24"
                  >
                    <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M19 9l-7 7-7-7" />
                  </svg>
                </button>

                {open && (
                  <div className="absolute top-full left-0 mt-1 z-50 min-w-[280px] bg-card border border-border rounded-lg shadow-lg py-1">
                    {sortedStrategies.map((strat) => {
                      const isActive = strat.id === selectedId;
                      const active = hasActivity(strat);
                      return (
                        <button
                          key={strat.id}
                          onClick={() => {
                            if (active) {
                              setSelectedId(strat.id);
                              setOpen(false);
                            }
                          }}
                          disabled={!active}
                          className={cn(
                            "w-full flex items-center justify-between gap-3 px-3 py-2 text-xs font-mono transition-colors text-left",
                            isActive
                              ? "bg-emerald-500/10 text-emerald-400"
                              : active
                                ? "text-foreground hover:bg-muted"
                                : "text-muted-foreground/40 cursor-not-allowed"
                          )}
                        >
                          <div className="flex items-center gap-2">
                            <span className={cn("font-semibold", !active && "line-through decoration-muted-foreground/20")}>
                              {strat.label}
                            </span>
                            {strat.hasPaperTrading && (
                              <span className="h-1.5 w-1.5 rounded-full bg-emerald-500 animate-pulse" title="Live paper trading" />
                            )}
                          </div>
                          <div className="flex items-center gap-2">
                            {strat.hasExperiments && (
                              <span className={cn(
                                "text-[10px]",
                                isActive ? "text-emerald-400/70" : active ? "text-muted-foreground" : "text-muted-foreground/30"
                              )}>
                                {strat.experimentCount} exp
                              </span>
                            )}
                            {!active && (
                              <span className="text-[10px] italic text-muted-foreground/30">
                                no data
                              </span>
                            )}
                          </div>
                        </button>
                      );
                    })}
                  </div>
                )}
              </div>
            )}
          </div>

          <nav className="flex items-center gap-1">
            {links.map((link) => (
              <Link
                key={link.href}
                href={link.href}
                className={cn(
                  "px-3 py-1.5 text-xs font-medium rounded-md transition-colors",
                  pathname === link.href
                    ? "bg-primary text-primary-foreground"
                    : "text-muted-foreground hover:text-foreground hover:bg-accent"
                )}
              >
                {link.label}
              </Link>
            ))}
          </nav>
        </div>
      </div>
    </header>
  );
}

